const precio = 25;
const cantidad = 3;
const descuento = 5;

// Suma: solo para practicar el operador +
const suma = precio + descuento;
console.log("Suma:", suma); // 30

// Resta: aplicar descuento a un precio
const precioConDescuento = precio - descuento;
console.log("Precio con descuento:", precioConDescuento); // 20

// Multiplicación: total a pagar por tres unidades
const totalAPagar = precioConDescuento * cantidad;
console.log("Total a pagar:", totalAPagar); // 60

// División: repartir el total entre dos personas
const precioPorPersona = totalAPagar / 2;
console.log("Precio por persona:", precioPorPersona); // 30

// Módulo: obtenemos el resto
const numero = 17;
const resto = numero % 2;
console.log("17 dividido entre 2 da resto:", resto); // 1

// Potencia: área de un cuadrado
const lado = 4;
const area = lado ** 2;
console.log("Área del cuadrado:", area); // 16`}),(0,k.jsxs)(`section`,{className:`jsm-challenge`,children:[(0,k.jsx)(`h3`,{children:`Micropráctica · Cambia y predice`}),(0,k.jsxs)(`ol`,{children:[(0,k.jsxs)(`li`,{children:[`Cambia `,(0,k.jsx)(`code`,{children:`cantidad`}),` a 4. ¿Qué total esperas?`]}),(0,k.jsxs)(`li`,{children:[`Cambia `,(0,k.jsx)(`code`,{children:`lado`}),` a 6 y calcula el área antes de ejecutar.`]}),(0,k.jsxs)(`li`,{children:[`Crea `,(0,k.jsx)(`code`,{children:`mitad`}),` con la mitad de 18 usando `,(0,k.jsx)(`code`,{children:`/`}),`.`]})]})]})]}),(0,k.jsxs)(`section`,{className:`jsm-section`,children:[(0,k.jsxs)(`h2`,{children:[`El módulo `,(0,k.jsx)(`code`,{children:`%`}),` no es un porcentaje`]}),(0,k.jsxs)(`p`,{children:[`El módulo devuelve lo que sobra después de una división. Por ejemplo, `,(0,k.jsx)(`code`,{children:`10 % 3`}),` da 1 porque 10 dividido entre 3 deja 1 de resto.`]}),(0,k.jsx)(Ta,{children:`console.log(10 % 3); // 1
